// Función para verificar el estado del sitio
async function checkWebsiteStatus() {
    try {
        const response = await fetch('https://tu-sitio-web.com'); // Reemplaza con la URL de tu sitio
        if (!response.ok) {
            throw new Error('El sitio web no está disponible');
        }
        return response.json(); // Suponiendo que la página de mantenimiento tiene un endpoint para verificar el estado
    } catch (error) {
        return { maintenance: true, message: error.message };
    }
}

// Función para redirigir al usuario
function redirectToMaintenancePage(message) {
    const maintenanceData = checkWebsiteStatus();

    maintenanceData.then(data => {
        if (data.maintenance) {
            alert(message || 'El sitio está en mantenimiento. Por favor, inténtalo de nuevo más tarde.');
            window.location.href = 'https://tu-pagina-de-mantenimiento.com'; // URL de la página de mantenimiento
        }
    });
}

// Llamar a la función al cargar la página
window.onload = () => {
    redirectToMaintenancePage('El sitio está experimentando problemas temporales.');
};
